/**
 * @summary Search Quran text
 */
export const getSearchQuranUrl = (params: SearchQuranParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/quran/search?${stringifiedParams}`
    : `/api/quran/search`;
};

export const searchQuran = async (
  params: SearchQuranParams,
  options?: RequestInit,
): Promise<QuranSearchResults> => {
  return customFetch<QuranSearchResults>(getSearchQuranUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getSearchQuranQueryKey = (params?: SearchQuranParams) => {
  return [`/api/quran/search`, ...(params ? [params] : [])] as const;
};

